/**
 * emit to subscription queries of type FindMRPRun,
 * but only if the id matches
 *
 * @param		entity	MRPRun
 */
	protected void emitFindMRPRun( MRPRun entity ) {
		LOGGER.info("handling emitFindMRPRun" );
		
	    queryUpdateEmitter.emit(FindMRPRunQuery.class,
	                            query -> query.getFilter().getMRPRunId().equals(entity.getMRPRunId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllMRPRun
	 * 
	 * @param		entity	MRPRun
	 */
	protected void emitFindAllMRPRun( MRPRun entity ) {
		LOGGER.info("handling emitFindAllMRPRun" );
		
	    queryUpdateEmitter.emit(FindAllMRPRunQuery.class,
	                            query -> true,
	                            entity);
	}

